-- Run once against the same database as PostgresConnection if login returns 500
-- ("could not issue tokens" / relation "RefreshTokens" does not exist).
-- Matches EF Core default mapping for Infrastructure.Security.Entities.RefreshToken.

CREATE TABLE IF NOT EXISTS "RefreshTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Token" text NOT NULL,
    "Expires" timestamp without time zone NOT NULL,
    "Created" timestamp without time zone NOT NULL,
    "Revoked" timestamp without time zone NULL,
    "UserId" text NOT NULL,
    CONSTRAINT "FK_RefreshTokens_AspNetUsers_UserId"
        FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_RefreshTokens_UserId" ON "RefreshTokens" ("UserId");
